import { describe, expect, test } from 'vitest';
import { LANGUAGE_PROMPT_SUPPRESSION_DAYS } from './regionPrefCookie';
import { EU_DOMESTIC_SFCC_SITE_ID, SUPPORTED_EU_LANGUAGES, shouldShowLanguagePrompt } from './shouldShowLanguagePrompt';

const NOW = 1_700_000_000; // an arbitrary fixed epoch-seconds instant
const SECONDS_PER_DAY = 24 * 60 * 60;

const baseInput = {
  sfccSiteId: EU_DOMESTIC_SFCC_SITE_ID,
  currentLanguage: 'it',
  browserLanguages: ['fr-FR'],
  suppressedAt: undefined,
  now: NOW,
};

describe('shouldShowLanguagePrompt — six required branches', () => {
  test('1. non-EU site never shows, regardless of a real language mismatch', () => {
    expect(shouldShowLanguagePrompt({ ...baseInput, sfccSiteId: 'ZimmermannAU' })).toEqual({ show: false });
  });

  test('2. EU site, browser language matches the current site language -> false', () => {
    expect(
      shouldShowLanguagePrompt({ ...baseInput, currentLanguage: 'it', browserLanguages: ['it-IT'] }),
    ).toEqual({ show: false });
  });

  test('3. EU site, browser language differs and is one of the four -> true, with the right target', () => {
    expect(
      shouldShowLanguagePrompt({ ...baseInput, currentLanguage: 'it', browserLanguages: ['fr-FR'] }),
    ).toEqual({ show: true, targetLanguage: 'fr' });
  });

  test('4. EU site, browser language is none of the four -> false', () => {
    expect(
      shouldShowLanguagePrompt({ ...baseInput, currentLanguage: 'it', browserLanguages: ['de-DE'] }),
    ).toEqual({ show: false });
  });

  test('5. within the suppression window -> false, even though the language would otherwise mismatch', () => {
    const suppressedAt = NOW - 1 * SECONDS_PER_DAY; // dismissed yesterday, well inside 7 days
    expect(shouldShowLanguagePrompt({ ...baseInput, suppressedAt })).toEqual({ show: false });
  });

  test('6. suppression window lapsed -> true again', () => {
    const suppressedAt = NOW - (LANGUAGE_PROMPT_SUPPRESSION_DAYS + 1) * SECONDS_PER_DAY; // 8 days ago
    expect(shouldShowLanguagePrompt({ ...baseInput, suppressedAt })).toEqual({ show: true, targetLanguage: 'fr' });
  });
});

describe('shouldShowLanguagePrompt — primary-subtag extraction, both sides', () => {
  test('fr-FR reduces to fr and matches a bare "fr" current language (would wrongly mismatch on exact string equality)', () => {
    expect(
      shouldShowLanguagePrompt({ ...baseInput, currentLanguage: 'fr', browserLanguages: ['fr-FR'] }),
    ).toEqual({ show: false });
  });

  test('en-GB (a full tag as the current site language) reduces to en and matches a browser reporting en-AU', () => {
    expect(
      shouldShowLanguagePrompt({ ...baseInput, currentLanguage: 'en-GB', browserLanguages: ['en-AU'] }),
    ).toEqual({ show: false });
  });
});

describe('shouldShowLanguagePrompt — supporting behaviour', () => {
  test('exactly the suppression-window boundary instant still counts as suppressed (now < end, not <=)', () => {
    const suppressedAt = NOW - LANGUAGE_PROMPT_SUPPRESSION_DAYS * SECONDS_PER_DAY;
    // now === suppressedAt + window exactly -> window has *just* lapsed, so it must show again.
    expect(shouldShowLanguagePrompt({ ...baseInput, suppressedAt, now: suppressedAt + LANGUAGE_PROMPT_SUPPRESSION_DAYS * SECONDS_PER_DAY })).toEqual({
      show: true,
      targetLanguage: 'fr',
    });
  });

  test('an empty browserLanguages array never throws and never shows', () => {
    expect(() => shouldShowLanguagePrompt({ ...baseInput, browserLanguages: [] })).not.toThrow();
    expect(shouldShowLanguagePrompt({ ...baseInput, browserLanguages: [] })).toEqual({ show: false });
  });

  test('SUPPORTED_EU_LANGUAGES is exactly the four EU-domestic primary languages', () => {
    expect(SUPPORTED_EU_LANGUAGES).toEqual(['en', 'fr', 'it', 'es']);
  });
});

