1	/**
2	 * The `zimm-region-pref` cookie — records when a shopper dismissed or acted on a regional
3	 * prompt, so the same prompt doesn't re-fire on every page load. One cookie, two independent
4	 * flags:
5	 *
6	 * - `l` — language-mismatch prompt (SFCC-689), epoch seconds.
7	 * - `c` — country-mismatch prompt (SFCC-823), epoch seconds.
8	 *
9	 * Wire format (exact): `zimm-region-pref=1|l=<epochSeconds>|c=<epochSeconds>`, either flag
10	 * optional, attributes `path=/; samesite=lax; secure; max-age=<seconds>`. No `s` (manual
11	 * selection) flag — nothing in SFCC-831/689 writes one, and the leading `1|` version prefix
12	 * means a future flag can be added without breaking anything already deployed.
13	 *
14	 * Split in two, deliberately:
15	 * - The parse/serialise half below is pure and isomorphic — it never touches `document`, which
16	 *   is what would let a server-side reader (e.g. a future `request-processor.js` reading the
17	 *   `Cookie` header) reuse it unchanged. Verify with `grep document` if this file is ever
18	 *   touched again — see this step's own pass criteria.
19	 * - `getRegionPrefCookie`/`setRegionPrefCookie` are the only functions that touch
20	 *   `document.cookie`, and are the only two that can fail: Safari private browsing throws on
21	 *   *reading* `document.cookie` (well-documented WebKit behaviour), and the same applies to
22	 *   *writing* it. Both are guarded so a shopper in private mode just never gets the
23	 *   suppression remembered — never a hard failure.
24	 */
25	
26	/** All epoch values below are **seconds**, not `Date.now()` milliseconds — matches the wire format. */
27	export const COOKIE_NAME = 'zimm-region-pref';
28	
29	/**
30	 * Read-time suppression window for the language-mismatch prompt (SFCC-689), enforced by
31	 * `shouldShowLanguagePrompt.ts` against `l`'s timestamp — not a cookie-native expiry. Exported
32	 * as a named constant (rather than inlined at every call site) because the build plan's own
33	 * open questions flag this exact number as still being negotiated against REG-019's "indefinite"
34	 * wording; a change stays a one-line edit here.
35	 */
36	export const LANGUAGE_PROMPT_SUPPRESSION_DAYS = 7;
37	
38	const COOKIE_VERSION = '1';
39	
40	/**
41	 * Browsers cap a cookie's own Max-Age at 400 days regardless of what's requested (the
42	 * Chrome-led cookie-expiry ceiling most browsers now enforce) — set to that practical ceiling
43	 * rather than tying it to `LANGUAGE_PROMPT_SUPPRESSION_DAYS`, because this one cookie also
44	 * carries the *country*-prompt timestamp (`c`), whose own suppression policy is a separate,
45	 * still-open decision that may end up indefinite (build plan open question #1). The language
46	 * prompt itself re-fires strictly on the `LANGUAGE_PROMPT_SUPPRESSION_DAYS` read-time check,
47	 * never on this cookie expiring — so a longer cookie lifetime here only avoids losing the
48	 * country flag early, it cannot make the language prompt stay suppressed longer than intended.
49	 */
50	const COOKIE_MAX_AGE_SECONDS = 400 * 24 * 60 * 60;
51	
52	/** Parsed shape of the cookie's value. Either field may be absent — nothing recorded yet. */
53	export type RegionPrefCookieValue = {
54	  readonly languageSuppressedAt?: number;
55	  readonly countrySuppressedAt?: number;
56	};
57	
58	/**
59	 * Parses the cookie's raw value (the part after `zimm-region-pref=`). Pure — no `document`
60	 * reference. Any unrecognised shape (wrong version, garbage, non-numeric timestamp) returns a
61	 * safe empty state rather than throwing, so a malformed or future-versioned cookie never breaks
62	 * the page that reads it.
63	 */
64	export function parseRegionPrefCookie(raw: string | null | undefined): RegionPrefCookieValue {
65	  if (!raw) {
66	    return {};
67	  }
68	
69	  const segments = raw.split('|');
70	  if (segments[0] !== COOKIE_VERSION) {
71	    // Unknown/future version, or plain garbage — never guess at a shape we don't recognise.
72	    // This is also what keeps a future version bump additive: an old client reading a newer
73	    // cookie just sees "nothing recorded" instead of misparsing it.
74	    return {};
75	  }
76	
77	  const result: { languageSuppressedAt?: number; countrySuppressedAt?: number } = {};
78	
79	  for (const segment of segments.slice(1)) {
80	    const separatorIndex = segment.indexOf('=');
81	    if (separatorIndex === -1) {
82	      continue;
83	    }
84	    const key = segment.slice(0, separatorIndex);
85	    const parsedValue = Number(segment.slice(separatorIndex + 1));
86	    if (!Number.isFinite(parsedValue) || parsedValue < 0) {
87	      continue;
88	    }
89	
90	    if (key === 'l') {
91	      result.languageSuppressedAt = parsedValue;
92	    } else if (key === 'c') {
93	      result.countrySuppressedAt = parsedValue;
94	    }
95	    // Any other key (including a hypothetical future `s`) is deliberately ignored, not stored —
96	    // this file must not be the thing that starts recognising a flag before it's specified.
97	  }
98	
99	  return result;
100	}
101	
102	/**
103	 * Serialises just the cookie's raw value (no attributes) — pure, no `document` reference.
104	 * Exists separately from {@link serialiseRegionPrefCookie} so parse/serialise can be
105	 * round-tripped in isolation from the attribute string.
106	 */
107	export function serialiseRegionPrefCookieValue(value: RegionPrefCookieValue): string {
108	  const segments = [COOKIE_VERSION];
109	  if (value.languageSuppressedAt !== undefined) {
110	    segments.push(`l=${Math.trunc(value.languageSuppressedAt)}`);
111	  }
112	  if (value.countrySuppressedAt !== undefined) {
113	    segments.push(`c=${Math.trunc(value.countrySuppressedAt)}`);
114	  }
115	  return segments.join('|');
116	}
117	
118	/**
119	 * Serialises the full `document.cookie`-assignable string, attributes included. Pure — no
120	 * `document` reference; see {@link setRegionPrefCookie} for the function that actually writes it.
121	 */
122	export function serialiseRegionPrefCookie(value: RegionPrefCookieValue): string {
123	  const rawValue = serialiseRegionPrefCookieValue(value);
124	  return `${COOKIE_NAME}=${rawValue}; path=/; samesite=lax; secure; max-age=${COOKIE_MAX_AGE_SECONDS}`;
125	}
126	
127	/**
128	 * Reads and parses the cookie from `document.cookie`. SSR-guarded (`typeof document ===
129	 * 'undefined'`) and survives a throwing getter (Safari private browsing) — both cases return
130	 * the same safe empty state as an unset cookie, never throw.
131	 */
132	export function getRegionPrefCookie(): RegionPrefCookieValue {
133	  if (typeof document === 'undefined') {
134	    return {};
135	  }
136	
137	  let cookieString: string;
138	  try {
139	    cookieString = document.cookie;
140	  } catch {
141	    return {};
142	  }
143	
144	  const prefix = `${COOKIE_NAME}=`;
145	  const match = cookieString.split('; ').find((entry) => entry.startsWith(prefix));
146	  if (!match) {
147	    return {};
148	  }
149	
150	  return parseRegionPrefCookie(match.slice(prefix.length));
151	}
152	
153	/**
154	 * Writes the cookie via `document.cookie`. SSR-guarded and survives a throwing setter (Safari
155	 * private browsing) — failing to persist the suppression window just means the prompt may show
156	 * again next visit, which must never be a fatal error for the caller.
157	 */
158	export function setRegionPrefCookie(value: RegionPrefCookieValue): void {
159	  if (typeof document === 'undefined') {
160	    return;
161	  }
162	
163	  try {
164	    document.cookie = serialiseRegionPrefCookie(value);
165	  } catch {
166	    // Deliberately swallowed — see the doc comment above.
167	  }
168	}
169

