 *   is what would let a server-side reader (e.g. a future `request-processor.js` reading the
 *   `Cookie` header) reuse it unchanged. Verify with `grep document` if this file is ever
 *   touched again — see this step's own pass criteria.
 * - `getRegionPrefCookie`/`setRegionPrefCookie` are the only functions that touch
 *   `document.cookie`, and are the only two that can fail: Safari private browsing throws on
 *   *reading* `document.cookie` (well-documented WebKit behaviour), and the same applies to
 *   *writing* it. Both are guarded so a shopper in private mode just never gets the
 *   suppression remembered — never a hard failure.
 */

/** All epoch values below are **seconds**, not `Date.now()` milliseconds — matches the wire format. */
export const COOKIE_NAME = 'zimm-region-pref';

/**
 * Read-time suppression window for the language-mismatch prompt (SFCC-689), enforced by
 * `shouldShowLanguagePrompt.ts` against `l`'s timestamp — not a cookie-native expiry. Exported
 * as a named constant (rather than inlined at every call site) because the build plan's own
 * open questions flag this exact number as still being negotiated against REG-019's "indefinite"
 * wording; a change stays a one-line edit here.
 */
export const LANGUAGE_PROMPT_SUPPRESSION_DAYS = 7;

const COOKIE_VERSION = '1';

/**
 * Browsers cap a cookie's own Max-Age at 400 days regardless of what's requested (the
 * Chrome-led cookie-expiry ceiling most browsers now enforce) — set to that practical ceiling
 * rather than tying it to `LANGUAGE_PROMPT_SUPPRESSION_DAYS`, because this one cookie also
 * carries the *country*-prompt timestamp (`c`), whose own suppression policy is a separate,
 * still-open decision that may end up indefinite (build plan open question #1). The language
 * prompt itself re-fires strictly on the `LANGUAGE_PROMPT_SUPPRESSION_DAYS` read-time check,
 * never on this cookie expiring — so a longer cookie lifetime here only avoids losing the
 * country flag early, it cannot make the language prompt stay suppressed longer than intended.
 */
const COOKIE_MAX_AGE_SECONDS = 400 * 24 * 60 * 60;

/** Parsed shape of the cookie's value. Either field may be absent — nothing recorded yet. */
export type RegionPrefCookieValue = {
  readonly languageSuppressedAt?: number;
  readonly countrySuppressedAt?: number;
};

/**
 * Parses the cookie's raw value (the part after `zimm-region-pref=`). Pure — no `document`
 * reference. Any unrecognised shape (wrong version, garbage, non-numeric timestamp) returns a
 * safe empty state rather than throwing, so a malformed or future-versioned cookie never breaks
 * the page that reads it.
 */
export function parseRegionPrefCookie(raw: string | null | undefined): RegionPrefCookieValue {
  if (!raw) {
    return {};
  }

  const segments = raw.split('|');
  if (segments[0] !== COOKIE_VERSION) {
    // Unknown/future version, or plain garbage — never guess at a shape we don't recognise.
    // This is also what keeps a future version bump additive: an old client reading a newer
    // cookie just sees "nothing recorded" instead of misparsing it.
    return {};
  }

  const result: { languageSuppressedAt?: number; countrySuppressedAt?: number } = {};

  for (const segment of segments.slice(1)) {
    const separatorIndex = segment.indexOf('=');
    if (separatorIndex === -1) {
      continue;
    }
    const key = segment.slice(0, separatorIndex);
    const parsedValue = Number(segment.slice(separatorIndex + 1));
    if (!Number.isFinite(parsedValue) || parsedValue < 0) {
      continue;
    }

    if (key === 'l') {
      result.languageSuppressedAt = parsedValue;
    } else if (key === 'c') {
      result.countrySuppressedAt = parsedValue;
    }
    // Any other key (including a hypothetical future `s`) is deliberately ignored, not stored —
    // this file must not be the thing that starts recognising a flag before it's specified.
  }

  return result;
}

/**
 * Serialises just the cookie's raw value (no attributes) — pure, no `document` reference.
 * Exists separately from {@link serialiseRegionPrefCookie} so parse/serialise can be
 * round-tripped in isolation from the attribute string.
 */
export function serialiseRegionPrefCookieValue(value: RegionPrefCookieValue): string {
  const segments = [COOKIE_VERSION];
  if (value.languageSuppressedAt !== undefined) {
    segments.push(`l=${Math.trunc(value.languageSuppressedAt)}`);
  }
  if (value.countrySuppressedAt !== undefined) {
    segments.push(`c=${Math.trunc(value.countrySuppressedAt)}`);
  }
  return segments.join('|');
}

/**
 * Serialises the full `document.cookie`-assignable string, attributes included. Pure — no
 * `document` reference; see {@link setRegionPrefCookie} for the function that actually writes it.
 */
export function serialiseRegionPrefCookie(value: RegionPrefCookieValue): string {
  const rawValue = serialiseRegionPrefCookieValue(value);
  return `${COOKIE_NAME}=${rawValue}; path=/; samesite=lax; secure; max-age=${COOKIE_MAX_AGE_SECONDS}`;
}

/**
 * Reads and parses the cookie from `document.cookie`. SSR-guarded (`typeof document ===
 * 'undefined'`) and survives a throwing getter (Safari private browsing) — both cases return
 * the same safe empty state as an unset cookie, never throw.
 */
export function getRegionPrefCookie(): RegionPrefCookieValue {
  if (typeof document === 'undefined') {
    return {};
  }

  let cookieString: string;
  try {
    cookieString = document.cookie;
  } catch {
    return {};
  }

  const prefix = `${COOKIE_NAME}=`;
  const match = cookieString.split('; ').find((entry) => entry.startsWith(prefix));
  if (!match) {
    return {};
  }

  return parseRegionPrefCookie(match.slice(prefix.length));
}

/**
 * Writes the cookie via `document.cookie`. SSR-guarded and survives a throwing setter (Safari
 * private browsing) — failing to persist the suppression window just means the prompt may show
 * again next visit, which must never be a fatal error for the caller.
 */
export function setRegionPrefCookie(value: RegionPrefCookieValue): void {
  if (typeof document === 'undefined') {
    return;
  }

  try {
    document.cookie = serialiseRegionPrefCookie(value);
  } catch {
    // Deliberately swallowed — see the doc comment above.
  }
}

